// The ops scaffolds `denext generate migration | seed | ci` emit — the same shape as
// `generate docker` (`docker-template.ts`): project-root files, the flavor auto-detected from
// the project with an optional override in the name slot, every file headed by a sentinel
// comment so a later tool can tell a generated file from a hand-written one, and nothing
// written over an existing file (that rule lives in `generate.ts`).
//
// - `migration <name>` writes `migrations/<UTC timestamp>_<name>.sql` and, the first time,
//   `tasks/migrate.ts`: a `defineTask` that applies every pending file in order on Deno's
//   built-in `node:sqlite`, recording each in a `_migrations` table (`denext task migrate`).
//   A Prisma or Drizzle project is pointed at its own migration tool instead.
// - `seed [name]` writes `tasks/seed.ts` (`denext task seed`): a `node:sqlite` seed by
//   default, a `PrismaClient` one in a Prisma project.
// - `ci` writes `.github/workflows/ci.yml`: Deno pinned to the version generating it, then the
//   project's own `check` task (else `deno fmt --check`, `deno lint`, `deno test`) and its
//   `build` (or, for a SPA, `export`) task.
//
// Build-time only; never imported by a shipped bundle.

import { join } from "@std/path";
import { detectDockerMode } from "./docker-template.ts";

/** One file an ops scaffold would write. */
export interface OpsPlanFile {
  /** Absolute path. */
  readonly path: string;
  /** Full contents. */
  readonly contents: string;
}

/** The ORM a project's migrations and seeds belong to. */
type DataFlavor = "sqlite" | "prisma" | "drizzle";

/** The sentinel line a generated file of `kind` opens with (`//` or `#` comment style). */
function sentinel(kind: "migration" | "seed" | "ci", comment: "//" | "--" | "#"): string {
  return `${comment} Generated by \`denext generate ${kind}\``;
}

async function exists(path: string): Promise<boolean> {
  try {
    await Deno.stat(path);
    return true;
  } catch {
    return false;
  }
}

/**
 * Detect the project's data layer: Prisma (`prisma/schema.prisma`), Drizzle
 * (`drizzle.config.*`), else plain `node:sqlite`. An explicit `sqlite` | `prisma` | `drizzle`
 * override wins.
 *
 * @param projectDir The project root.
 * @param override The name-slot override, if any.
 * @returns The flavor.
 */
async function detectDataFlavor(
  projectDir: string,
  override?: string,
): Promise<DataFlavor> {
  const o = (override ?? "").trim().toLowerCase();
  if (o === "sqlite" || o === "prisma" || o === "drizzle") return o;
  if (await exists(join(projectDir, "prisma", "schema.prisma"))) return "prisma";
  for (const ext of ["ts", "js", "mjs", "json"]) {
    if (await exists(join(projectDir, `drizzle.config.${ext}`))) return "drizzle";
  }
  return "sqlite";
}

/** A migration/seed name as a file-safe slug (`Add users` → `add_users`). */
export function slugName(name: string): string {
  return name.trim().toLowerCase().replace(/[^a-z0-9]+/g, "_").replace(/^_+|_+$/g, "");
}

/** `20261007T093000` → `20261007093000`: the UTC timestamp a migration file is ordered by. */
function migrationStamp(now: Date): string {
  return now.toISOString().replace(/[-:T]/g, "").slice(0, 14);
}

/** The SQL file one migration starts as. */
function migrationSql(slug: string): string {
  return `${sentinel("migration", "--")} — applied in file-name order by \`denext task migrate\`.
-- Write forward-only SQL; each file runs once, inside a transaction.

-- ${slug}
CREATE TABLE IF NOT EXISTS example (
  id INTEGER PRIMARY KEY,
  created_at TEXT NOT NULL DEFAULT (datetime('now'))
);
`;
}

/** `tasks/migrate.ts`: applies pending `migrations/*.sql` on `node:sqlite`. */
const MIGRATE_TASK = `${sentinel("migration", "//")} — run it with \`denext task migrate\`.
//
// Applies every \`migrations/*.sql\` not yet recorded in the \`_migrations\` table, in file-name
// order, each inside its own transaction, on Deno's built-in SQLite (no npm). DB_PATH picks the
// database file (default app.db) — the same one lib/db.ts opens.
import { DatabaseSync } from "node:sqlite";
import { defineTask } from "denext/server";

const DIR = new URL("../migrations/", import.meta.url);

export default defineTask({
  description: "Apply pending SQL migrations",
  handler: async () => {
    const db = new DatabaseSync(Deno.env.get("DB_PATH") ?? "app.db");
    try {
      db.exec(
        "CREATE TABLE IF NOT EXISTS _migrations (name TEXT PRIMARY KEY, applied_at TEXT NOT NULL)",
      );
      const done = new Set(
        db.prepare("SELECT name FROM _migrations").all().map((r) => String(r.name)),
      );
      const files: string[] = [];
      for await (const entry of Deno.readDir(DIR)) {
        if (entry.isFile && entry.name.endsWith(".sql")) files.push(entry.name);
      }
      const pending = files.sort().filter((name) => !done.has(name));
      for (const name of pending) {
        const sql = await Deno.readTextFile(new URL(name, DIR));
        db.exec("BEGIN");
        try {
          db.exec(sql);
          db.prepare("INSERT INTO _migrations (name, applied_at) VALUES (?, ?)")
            .run(name, new Date().toISOString());
          db.exec("COMMIT");
        } catch (err) {
          db.exec("ROLLBACK");
          throw new Error(\`migration \${name} failed: \${(err as Error).message}\`);
        }
      }
      return pending.length ? \`applied \${pending.join(", ")}\` : "up to date";
    } finally {
      db.close();
    }
  },
});
`;

/**
 * The files `denext generate migration <name>` writes: the timestamped SQL file, plus the
 * `tasks/migrate.ts` runner when the project has none.
 *
 * @param projectDir The project root.
 * @param name The migration's name (`add_users`).
 * @param now The clock (tests pin it).
 * @returns The files, in write order.
 * @throws For a Prisma or Drizzle project (their own tools own migrations), or an empty name.
 */
export async function migrationPlan(
  projectDir: string,
  name: string,
  now: Date = new Date(),
): Promise<OpsPlanFile[]> {
  const flavor = await detectDataFlavor(projectDir);
  if (flavor === "prisma") {
    throw new Error(
      "denext: this is a Prisma project — create migrations with `prisma migrate dev --name " +
        `${slugName(name) || "<name>"}\` (denext runs \`prisma migrate deploy\` on its own).`,
    );
  }
  if (flavor === "drizzle") {
    throw new Error(
      "denext: this is a Drizzle project — create migrations with `drizzle-kit generate`.",
    );
  }
  const slug = slugName(name);
  if (!slug) throw new Error(`denext: migration name "${name}" has no letters or digits.`);
  const plan: OpsPlanFile[] = [{
    path: join(projectDir, "migrations", `${migrationStamp(now)}_${slug}.sql`),
    contents: migrationSql(slug),
  }];
  const runner = join(projectDir, "tasks", "migrate.ts");
  if (!(await exists(runner))) plan.push({ path: runner, contents: MIGRATE_TASK });
  return plan;
}

/** `tasks/seed.ts` on `node:sqlite`. */
function sqliteSeed(): string {
  return `${sentinel("seed", "//")} — run it with \`denext task seed\`.
//
// Inserts development data. Keep it idempotent (INSERT OR IGNORE / upserts) so it can run
// again; run \`denext task migrate\` first so the tables exist.
import { DatabaseSync } from "node:sqlite";
import { defineTask } from "denext/server";

export default defineTask({
  description: "Seed the database with development data",
  handler: () => {
    const db = new DatabaseSync(Deno.env.get("DB_PATH") ?? "app.db");
    try {
      const insert = db.prepare("INSERT OR IGNORE INTO example (id) VALUES (?)");
      db.exec("BEGIN");
      for (const id of [1, 2, 3]) insert.run(id);
      db.exec("COMMIT");
      return "seeded";
    } finally {
      db.close();
    }
  },
});
`;
}

/** `tasks/seed.ts` through the project's `PrismaClient`. */
function prismaSeed(): string {
  return `${sentinel("seed", "//")} — run it with \`denext task seed\`.
//
// Inserts development data through Prisma. Keep it idempotent (upsert) so it can run again.
import { PrismaClient } from "@prisma/client";
import { defineTask } from "denext/server";

export default defineTask({
  description: "Seed the database with development data",
  handler: async () => {
    const prisma = new PrismaClient();
    try {
      // await prisma.user.upsert({ where: { email: "ada@example.com" }, update: {},
      //   create: { email: "ada@example.com", name: "Ada" } });
      return "seeded";
    } finally {
      await prisma.$disconnect();
    }
  },
});
`;
}

/**
 * The file `denext generate seed [flavor]` writes: `tasks/seed.ts` for the detected data layer
 * (`sqlite` | `prisma`; Drizzle gets the `node:sqlite` shape to adapt).
 *
 * @param projectDir The project root.
 * @param override `sqlite` | `prisma` | `drizzle`, or empty to detect.
 * @returns The file.
 */
export async function seedPlan(projectDir: string, override?: string): Promise<OpsPlanFile[]> {
  const o = (override ?? "").trim().toLowerCase();
  if (o && o !== "seed" && !["sqlite", "prisma", "drizzle"].includes(o)) {
    throw new Error(`denext: unknown seed flavor "${override}" (expected: sqlite | prisma).`);
  }
  const flavor = await detectDataFlavor(projectDir, o);
  return [{
    path: join(projectDir, "tasks", "seed.ts"),
    contents: flavor === "prisma" ? prismaSeed() : sqliteSeed(),
  }];
}

/** The project's `deno.json` / `deno.jsonc` task names (empty when there is none). */
async function taskNames(projectDir: string): Promise<Set<string>> {
  for (const file of ["deno.json", "deno.jsonc"]) {
    try {
      const text = await Deno.readTextFile(join(projectDir, file));
      const tasks = /"tasks"\s*:\s*\{([^}]*)\}/.exec(text)?.[1] ?? "";
      return new Set([...tasks.matchAll(/"([^"]+)"\s*:/g)].map((m) => m[1]));
    } catch { /* try the next */ }
  }
  return new Set();
}

/** The workflow's check steps: the project's `check` task, else fmt + lint + test. */
function checkSteps(tasks: Set<string>): string {
  if (tasks.has("check")) return "      - run: deno task check\n";
  return "      - run: deno fmt --check\n      - run: deno lint\n" +
    (tasks.has("test") ? "      - run: deno task test\n" : "      - run: deno test -A\n");
}

/**
 * The file `denext generate ci [github]` writes: `.github/workflows/ci.yml`.
 *
 * @param projectDir The project root.
 * @param override `github` (the only provider), or empty.
 * @returns The file.
 */
export async function ciPlan(projectDir: string, override?: string): Promise<OpsPlanFile[]> {
  const o = (override ?? "").trim().toLowerCase();
  if (o && o !== "ci" && o !== "github") {
    throw new Error(`denext: unknown CI provider "${override}" (expected: github).`);
  }
  const tasks = await taskNames(projectDir);
  const spa = (await detectDockerMode(projectDir)) === "static";
  const buildTask = spa && tasks.has("export") ? "export" : tasks.has("build") ? "build" : null;
  const contents = `${sentinel("ci", "#")} — Deno pinned to the version that generated it;
# bump it deliberately.
name: CI

on:
  push:
    branches: [main]
  pull_request:

permissions:
  contents: read

jobs:
  check:
    runs-on: ubuntu-latest
    steps:
      - uses: actions/checkout@v4
      - uses: denoland/setup-deno@v2
        with:
          deno-version: v${Deno.version.deno}
          cache: true
${checkSteps(tasks)}${buildTask ? `      - run: deno task ${buildTask}\n` : ""}`;
  return [{ path: join(projectDir, ".github", "workflows", "ci.yml"), contents }];
}
